import unittest
from candidate import get_positive

class TestGetPositive(unittest.TestCase):
    def test_normal_positive_integers(self):
        self.assertEqual(get_positive([-1, 2, -4, 5, 6]), [2, 5, 6])

    def test_includes_positive_floats_and_excludes_zero(self):
        self.assertEqual(get_positive([0.0, -1.5, 3.2, 0, 4]), [3.2, 4])

    def test_bool_values_filtered(self):
        self.assertEqual(get_positive([True, False, 0, 1]), [True, 1])

    def test_empty_list_returns_empty(self):
        self.assertEqual(get_positive([]), [])

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            get_positive(None)

    def test_non_numeric_element_raises_type_error(self):
        with self.assertRaises(TypeError):
            get_positive(['a', 1])

    def test_original_list_unchanged(self):
        original = [1, -2, 3]
        copy = original[:]
        get_positive(original)
        self.assertEqual(original, copy)

    def test_preserves_order_of_positives(self):
        data = [5, -1, 3, -2, 4]
        self.assertEqual(get_positive(data), [5, 3, 4])

    def test_large_integers(self):
        large = [10**18, -10**18, 10**19]
        self.assertEqual(get_positive(large), [10**18, 10**19])

    def test_negative_only(self):
        self.assertEqual(get_positive([-5, -2, -3]), [])

    def test_mixed_types_without_error(self):
        # All elements are numeric types; bool, int, float
        data = [True, 0, 1.5, -1, 0.0]
        self.assertEqual(get_positive(data), [True, 1.5])

if __name__ == '__main__':
    unittest.main()
